using System.Text.Json;
using NewManga.CoreClient.Commands;

namespace NewManga.CoreClient.Tests.Commands;

/// <summary>
/// Cross-implementation vectors: the Core's canonical-json/1 (Python
/// application.sources.model.canonical_bytes) and the Host's implementation
/// must produce byte-identical text and digests (C-17 §1/§5.2). The expected
/// strings below were generated by the Core implementation.
/// </summary>
public sealed class CanonicalJsonTests
{
    private const string A64 = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
    private const string B64 = "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";

    [Fact]
    public void RequestDigest_MatchesCoreVector()
    {
        var value = new Dictionary<string, object?>
        {
            ["operation_id"] = "op-ABC123",
            ["plan_id"] = "pl-1",
            ["plan_digest"] = A64,
            ["kind"] = "resync",
        };

        Assert.Equal(
            "{\"kind\":\"resync\",\"operation_id\":\"op-ABC123\"," +
            "\"plan_digest\":\"" + A64 + "\",\"plan_id\":\"pl-1\"}",
            CanonicalJson.Text(value));
        Assert.Equal(
            "16d82718644da1602d1a0f011043b759766ad494cfebc5fa5dfc48ba65e80d5c",
            CanonicalJson.Sha256Hex(value));
    }

    [Fact]
    public void AuthorizationDigest_MatchesCoreVector()
    {
        var sorted = new List<Dictionary<string, object?>>
        {
            new() { ["registry_id"] = "reg-a", ["generation"] = 1, ["identity_digest"] = A64 },
            new() { ["registry_id"] = "reg-b", ["generation"] = 2, ["identity_digest"] = B64 },
        };

        Assert.Equal(
            "[{\"generation\":1,\"identity_digest\":\"" + A64 + "\",\"registry_id\":\"reg-a\"}," +
            "{\"generation\":2,\"identity_digest\":\"" + B64 + "\",\"registry_id\":\"reg-b\"}]",
            CanonicalJson.Text(sorted));
        Assert.Equal(
            "a6d2eab2e260623eb415001e86acd89659f35f64cf0715153b289ebc26f308ee",
            CanonicalJson.Sha256Hex(sorted));
    }

    [Fact]
    public void MixedValue_MatchesCoreVector()
    {
        var value = new Dictionary<string, object?>
        {
            ["a"] = new List<object?> { 1, true, null },
            ["unicode"] = "测试",
            ["m"] = "q",
            ["z"] = "x",
        };

        Assert.Equal(
            "{\"a\":[1,true,null],\"m\":\"q\",\"unicode\":\"测试\",\"z\":\"x\"}",
            CanonicalJson.Text(value));
        Assert.Equal(
            "6ca34cba9b4227a2fce676a3658c7924747a96333293b5a7fc3f405a155c8df3",
            CanonicalJson.Sha256Hex(value));
    }

    [Fact]
    public void StringEscapes_MatchCoreVector()
    {
        var value = new Dictionary<string, object?>
        {
            ["text"] = "a\"b\\c\n\t",
        };

        Assert.Equal("{\"text\":\"a\\\"b\\\\c\\n\\t\"}", CanonicalJson.Text(value));
        Assert.Equal(
            "5142422fb010957a6db829bff842295a956f0eebe9d2c0b5940e2fa960d9d340",
            CanonicalJson.Sha256Hex(value));
    }

    [Fact]
    public void NonBmpKeys_AreOrderedByCodePoint_MatchesCoreVector()
    {
        // U+FFFD (65533) sorts before U+1D11E (119070) by code point; UTF-16
        // ordinal order would put the surrogate pair first (r4 P2-08).
        var value = new Dictionary<string, object?>
        {
            ["𝄞"] = "g-clef",
            ["�"] = "replacement",
        };

        Assert.Equal(
            "{\"\uFFFD\":\"replacement\",\"\U0001D11E\":\"g-clef\"}",
            CanonicalJson.Text(value));
        Assert.Equal(
            "dc00aaa5c52b095c2a302d7bb5d5b68b8d500253a0d4949ddf049e6dc26248c5",
            CanonicalJson.Sha256Hex(value));
    }
}
